#!/bin/bash
set -u

CONF=/etc/nginx/sites-enabled/app
BACKUP="${CONF}.bak.$(date +%Y%m%d%H%M%S)"

if [ -f "$CONF" ]; then
    cp -a "$CONF" "$BACKUP"
fi

nginx -t 2>&1 | head -n 20

# Пишем корректную конфигурацию
cat > "$CONF" <<'EOF'
server {
    listen 8080 default_server;
    listen [::]:8080 default_server;

    server_name localhost;

    root /srv/www;
    index index.html;

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF

if ! nginx -t; then
    echo "Ошибка: конфигурация по-прежнему невалидна" >&2
    if [ -f "$BACKUP" ]; then
        cp -a "$BACKUP" "$CONF"
        echo "Восстановлена резервная копия $BACKUP" >&2
    fi
    exit 1
fi

if [ -f /run/nginx.pid ] && kill -0 "$(cat /run/nginx.pid)" 2>/dev/null; then
    nginx -s reload
else
    nginx
fi

sleep 1
curl -s -o /dev/null -w "HTTP %{http_code}\n" http://localhost:8080/ || true

