```bash
#!/bin/bash
set -u

CONF_APP=/etc/nginx/sites-enabled/app
CONF_MAIN=/etc/nginx/nginx.conf
TS=$(date +%Y%m%d%H%M%S)

# Резервные копии
[ -f "$CONF_APP" ] && cp -a "$CONF_APP" "${CONF_APP}.bak.${TS}"
cp -a "$CONF_MAIN" "${CONF_MAIN}.bak.${TS}"

# Основной конфиг пишем самодостаточно: не подключаем sites-enabled,
# сервер описываем прямо в http-блоке. Это устраняет ошибку контекста
# директивы server_name, которая возникала при подключении файла app.
cat > "$CONF_MAIN" <<'EOF'
user www-data;
worker_processes auto;
pid /run/nginx.pid;

events {
    worker_connections 768;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    access_log /var/log/nginx/access.log;
    error_log  /var/log/nginx/error.log;

    sendfile on;
    keepalive_timeout 65;

    server {
        listen 8080 default_server;
        server_name localhost;

        root /srv/www;
        index index.html;

        location / {
            try_files $uri $uri/ =404;
        }
    }
}
EOF

# Битый файл app выводим из загрузки (он больше не подключается, но мешает путанице)
if [ -f "$CONF_APP" ]; then
    mv "$CONF_APP" "${CONF_APP}.broken.${TS}"
fi

if ! nginx -t; then
    echo "Ошибка: nginx -t не прошёл" >&2
    cp -a "${CONF_MAIN}.bak.${TS}" "$CONF_MAIN"
    [ -f "${CONF_APP}.broken.${TS}" ] && mv "${CONF_APP}.broken.${TS}" "$CONF_APP"
    exit 1
fi

mkdir -p /srv/www
[ -f /srv/www/index.html ] || echo "<h1>OK</h1>" > /srv/www/index.html

if [ -f /run/nginx.pid ] && kill -0 "$(cat /run/nginx.pid)" 2>/dev/null; then
    nginx -s reload
else
    nginx
fi

sleep 1
curl -s -o /dev/null -w "HTTP %{http_code}\n" http://localhost:8080/ || true
