#!/bin/bash
set -euo pipefail

CONF=/etc/nginx/sites-enabled/app
ROOT=/srv/www

if [ ! -f "$ROOT/index.html" ]; then
    echo "Ошибка: нет файла $ROOT/index.html" >&2
    exit 1
fi

# Резервная копия сломанного конфига
if [ -f "$CONF" ]; then
    cp -a "$CONF" "$CONF.broken.$(date +%Y%m%d%H%M%S)"
fi

# Минимальный корректный серверный блок
cat > "$CONF" <<'EOF'
server {
    listen 8080;
    listen [::]:8080;
    server_name localhost;

    root /srv/www;
    index index.html;

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF

# Проверка конфигурации
nginx -t

# Запуск или перезагрузка без systemd
if pgrep -x nginx >/dev/null 2>&1; then
    nginx -s reload
else
    nginx
fi

# Проверка ответа
sleep 1
curl -fsS http://localhost:8080/ >/dev/null && echo "OK: nginx отдаёт http://localhost:8080/"

